def absorb(self, args: Sequence[str]):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption:

    A & (A | B) = A, A | (A & B) = A

    Negative absorption:

    A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    result = []
    for arg in args:
        try:
            if arg in ("A", "~A", "B") and arg[-1] != "+":
                neg_arg = "~" + arg
                if neg_arg in args:
                    result.append(arg)
                    if neg_arg in ("A", "B"):
                        result.append(neg_arg)
        except IndexError:
            result.append(arg)
    return result

