def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    tags = set()
    code_block = False
    new_text = ""
    for word in text.split():
        if word.startswith("<") and word.endswith(">"):
            tag = word[1:-1]
            tags.add(tag)
            if replacer:
                new_word = replacer(tag)
                new_text += new_word + " "
            else:
                new_text += word + " "
        else:
            new_text += word + " "
            if code_block:
                code_block = False
            elif word == "<pre>":
                code_block = True
    return tags, new_text.strip()

